import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define LN_BLOCK 256

__global__ void cute_layernorm_kernel(
    float const* __restrict__ X,
    float const* __restrict__ W,
    float const* __restrict__ B,
    float* __restrict__ Y,
    int N, int M, float eps)
{
    int n = blockIdx.x;
    if (n >= N) return;

    // CuTe tensor views for this batch row
    Tensor gX = make_tensor(make_gmem_ptr(X + (size_t)n * M), make_shape(M), make_stride(Int<1>{}));
    Tensor gY = make_tensor(make_gmem_ptr(Y + (size_t)n * M), make_shape(M), make_stride(Int<1>{}));
    Tensor gW = make_tensor(make_gmem_ptr(W), make_shape(M), make_stride(Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(M), make_stride(Int<1>{}));

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    float local_sum = 0.f;
    float local_sqsum = 0.f;

    for (int i = tid; i < M; i += nthreads) {
        float v = gX(i);
        local_sum += v;
        local_sqsum += v * v;
    }

    // Warp-level reduction
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
        local_sqsum += __shfl_down_sync(0xffffffff, local_sqsum, offset);
    }

    __shared__ float warp_sum[LN_BLOCK / 32];
    __shared__ float warp_sqsum[LN_BLOCK / 32];

    int warp_id = tid / 32;
    int lane_id = tid % 32;

    if (lane_id == 0) {
        warp_sum[warp_id] = local_sum;
        warp_sqsum[warp_id] = local_sqsum;
    }
    __syncthreads();

    int num_warps = (nthreads + 31) / 32;

    __shared__ float mean_shared;
    __shared__ float invstd_shared;

    if (warp_id == 0) {
        float s = (lane_id < num_warps) ? warp_sum[lane_id] : 0.f;
        float sq = (lane_id < num_warps) ? warp_sqsum[lane_id] : 0.f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            s += __shfl_down_sync(0xffffffff, s, offset);
            sq += __shfl_down_sync(0xffffffff, sq, offset);
        }
        if (lane_id == 0) {
            float mean = s / (float)M;
            float var = sq / (float)M - mean * mean;
            if (var < 0.f) var = 0.f;
            float invstd = rsqrtf(var + eps);
            mean_shared = mean;
            invstd_shared = invstd;
        }
    }
    __syncthreads();

    float mean = mean_shared;
    float invstd = invstd_shared;

    for (int i = tid; i < M; i += nthreads) {
        float v = gX(i);
        float w = gW(i);
        float b = gB(i);
        float norm = (v - mean) * invstd;
        gY(i) = norm * w + b;
    }
}

torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda(), "All tensors must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Expect float32 tensor");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    int64_t norm_numel = w_c.numel();
    int64_t total_numel = x_c.numel();
    TORCH_CHECK(total_numel % norm_numel == 0, "shape mismatch");
    int N = (int)(total_numel / norm_numel);
    int M = (int)norm_numel;

    auto y = torch::empty_like(x_c);

    dim3 grid(N);
    dim3 block(LN_BLOCK);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_layernorm_kernel<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N, M, (float)eps);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE layernorm launch failed");
    return y;
}
"""

cute_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Layer Normalization using a custom CUTE kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm(x, self.weight, self.bias, self.eps)

